"""ARENA u07 的 10 道测验（沿用旧版题目，调整了解释措辞）"""
from unitlib import Q
QUIZ = [
  Q('随机变量 $X$ 取 0 的概率是 0.7，取 10 的概率是 0.3，$\\mathbb{E}[X]$ 是多少？', ['5', '3', '7', '10'], 1, '$0 \\times 0.7 + 10 \\times 0.3 = 3$。'),
  Q('$\\mathbb{E}[X] = 2$，$\\mathbb{E}[Y] = 5$，则 $\\mathbb{E}[3X - Y + 1]$ 等于？', ['2', '12', '6', '只有 $X$、$Y$ 独立时才能算'], 0, '期望是线性的，**不需要独立**：$3 \\times 2 - 5 + 1 = 2$。'),
  Q('$\\text{Var}(X) = 4$，则 $\\text{Var}(3X + 7)$ 等于？', ['19', '12', '43', '36'], 3, '平移不影响方差，缩放 3 倍让方差变成 $3^2 = 9$ 倍：$9 \\times 4 = 36$。'),
  Q('方差和标准差的关系是？', ['标准差是方差的平方', '两者总是相等', '标准差是方差的平方根', '标准差是方差的一半'], 2, '$\\sigma = \\sqrt{\\text{Var}(X)}$。标准差和原数据单位相同，更直观。'),
  Q('$X$、$Y$ **独立**，$\\text{Var}(X) = 2$，$\\text{Var}(Y) = 3$，$\\text{Var}(X - Y)$ 等于？', ['−1', '1', '6', '5'], 3, '$\\text{Var}(X - Y) = \\text{Var}(X) + (-1)^2\\,\\text{Var}(Y) = 2 + 3 = 5$。方差永远不会因为「减」而相减。'),
  Q('两个**正相关**的随机变量相加，和的方差和「独立时的方差之和」相比？', ['更大', '更小', '一样', '无法比较'], 0, '$\\text{Var}(X+Y) = \\text{Var}(X) + \\text{Var}(Y) + 2\\text{Cov}(X,Y)$，正相关时协方差为正，所以更大。'),
  Q('$X_1 \\sim \\mathcal{N}(1, 4)$ 和 $X_2 \\sim \\mathcal{N}(2, 9)$ 独立，$X_1 + X_2$ 服从什么分布？', ['$\\mathcal{N}(3, 5)$', '$\\mathcal{N}(3, 13)$', '$\\mathcal{N}(3, 36)$', '$\\mathcal{N}(1.5, 6.5)$'], 1, '独立正态变量之和仍是正态，均值相加 $1 + 2 = 3$，方差相加 $4 + 9 = 13$。注意 $\\mathcal{N}(\\mu, \\sigma^2)$ 的第二个参数是**方差**。'),
  Q('对正态分布，大约有多少比例的值落在 $\\mu \\pm 2\\sigma$ 之内？', ['68%', '50%', '95%', '99.7%'], 2, '68–95–99.7 法则：±1σ 约 68%，±2σ 约 95%，±3σ 约 99.7%。'),
  Q('10,000 个独立变量，每个方差为 1。它们的**平均值**的标准差是多少？', ['1', '0.01', '100', '0.0001'], 1, '平均值的方差 $= 1/10000$，标准差 $= \\sqrt{1/10000} = 0.01$。平均越多，越稳定。'),
  Q('为了让 $\\sum_{i=1}^{n} w_ix_i$ 的方差保持在 1 附近（$x_i$ 方差为 1，各项独立、均值为 0），权重 $w_i$ 的方差应该设为？', ['1', '$n$', '0', '$1/n$'], 3, '和的方差 $= n \\cdot \\text{Var}(w) \\cdot \\text{Var}(x) = n\\,\\text{Var}(w)$，要等于 1 就需要 $\\text{Var}(w) = 1/n$。这是 Xavier / Kaiming 初始化的核心思想。'),
]
